@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700&display=swap');

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Poppins', sans-serif;
}

:root {
    --bg-color: #121212;
    --sidebar-color: #000000;
    --card-bg: #181818;
    --card-hover: #282828;
    --text-color: #ffffff;
    --text-muted: #b3b3b3;
    --primary-color: #1db954;
    --primary-hover: #1ed760;
    --border-color: #282828;
}

body {
    background-color: var(--bg-color);
    color: var(--text-color);
    height: 100vh;
    overflow: hidden;
}

.app-container {
    display: flex;
    height: calc(100vh - 90px);
}

/* Sidebar */
.sidebar {
    width: 240px;
    background-color: var(--sidebar-color);
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 30px;
}

.logo {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 24px;
    font-weight: 700;
    color: var(--primary-color);
}

.nav-menu {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 15px;
}

.nav-menu li {
    display: flex;
    align-items: center;
    gap: 15px;
    color: var(--text-muted);
    font-weight: 500;
    cursor: pointer;
    padding: 10px;
    border-radius: 6px;
    transition: 0.2s;
}

.nav-menu li:hover,
.nav-menu li.active {
    color: var(--text-color);
    background-color: var(--card-hover);
}

.playlist-section h3 {
    font-size: 14px;
    color: var(--text-muted);
    margin-bottom: 10px;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.playlist-section ul {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 10px;
    max-height: 250px;
    overflow-y: auto;
}

.playlist-section li {
    color: var(--text-muted);
    font-size: 14px;
    cursor: pointer;
    transition: 0.2s;
}

.playlist-section li:hover {
    color: var(--text-color);
}

/* Main Content */
.main-content {
    flex: 1;
    background: linear-gradient(180deg, #2d2d2d 0%, var(--bg-color) 100%);
    overflow-y: auto;
    padding: 20px 30px;
}

.header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 30px;
}

.search-box {
    display: flex;
    align-items: center;
    background-color: var(--card-bg);
    padding: 10px 15px;
    border-radius: 30px;
    width: 350px;
    gap: 10px;
}

.search-box i {
    color: var(--text-muted);
}

.search-box input {
    background: none;
    border: none;
    outline: none;
    color: var(--text-color);
    width: 100%;
    font-size: 14px;
}

.user-profile {
    display: flex;
    align-items: center;
    gap: 20px;
}

.user-profile i {
    font-size: 18px;
    color: var(--text-muted);
    cursor: pointer;
}

.avatar img {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    object-fit: cover;
    cursor: pointer;
}

/* Banner */
.banner {
    background: linear-gradient(135deg, #1db954 0%, #191414 100%);
    border-radius: 12px;
    padding: 40px;
    margin-bottom: 40px;
}

.banner-content .tag {
    background-color: rgba(0, 0, 0, 0.3);
    padding: 4px 10px;
    font-size: 12px;
    font-weight: 600;
    border-radius: 4px;
    text-transform: uppercase;
}

.banner-content h1 {
    font-size: 36px;
    margin: 15px 0 10px;
}

.banner-content p {
    color: var(--text-muted);
    margin-bottom: 20px;
}

.btn-play-all {
    background-color: var(--text-color);
    color: var(--bg-color);
    border: none;
    padding: 12px 25px;
    border-radius: 30px;
    font-weight: 600;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 10px;
    transition: 0.2s;
}

.btn-play-all:hover {
    background-color: var(--primary-color);
    color: var(--text-color);
}

/* Songs Section */
.songs-section h2 {
    font-size: 22px;
    margin-bottom: 15px;
}

.song-list-header {
    display: grid;
    grid-template-columns: 50px 1fr 1fr 80px;
    padding: 10px 15px;
    color: var(--text-muted);
    border-bottom: 1px solid var(--border-color);
    font-size: 14px;
    font-weight: 500;
}

.song-list {
    display: flex;
    flex-direction: column;
    gap: 5px;
    margin-top: 10px;
}

.song-item {
    display: grid;
    grid-template-columns: 50px 1fr 1fr 80px;
    align-items: center;
    padding: 10px 15px;
    border-radius: 6px;
    cursor: pointer;
    transition: 0.2s;
}

.song-item:hover {
    background-color: var(--card-hover);
}

.song-item.active {
    background-color: var(--card-hover);
    color: var(--primary-color);
}

.song-item .song-index {
    color: var(--text-muted);
}

.song-item .song-details {
    display: flex;
    align-items: center;
    gap: 15px;
}

.song-item img {
    width: 45px;
    height: 45px;
    border-radius: 4px;
    object-fit: cover;
}

.song-item .title-artist h5 {
    font-size: 14px;
    font-weight: 500;
}

.song-item .title-artist p {
    font-size: 12px;
    color: var(--text-muted);
}

.song-item .album-name {
    color: var(--text-muted);
    font-size: 14px;
}

.song-item .song-duration {
    color: var(--text-muted);
    font-size: 14px;
}

/* Music Player Bar */
.music-player {
    position: fixed;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 90px;
    background-color: var(--sidebar-color);
    border-top: 1px solid var(--border-color);
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 20px;
    z-index: 1000;
}

.current-song {
    display: flex;
    align-items: center;
    gap: 15px;
    width: 300px;
}

.current-song img {
    width: 55px;
    height: 55px;
    border-radius: 4px;
    object-fit: cover;
}

.song-info h4 {
    font-size: 14px;
    font-weight: 500;
}

.song-info p {
    font-size: 12px;
    color: var(--text-muted);
}

.current-song i {
    font-size: 18px;
    color: var(--text-muted);
    cursor: pointer;
    margin-left: 10px;
}

.current-song i:hover,
.current-song i.active {
    color: var(--primary-color);
}

.player-center {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    width: 45%;
}

.player-controls {
    display: flex;
    align-items: center;
    gap: 25px;
}

.player-controls button {
    background: none;
    border: none;
    color: var(--text-muted);
    font-size: 16px;
    cursor: pointer;
    transition: 0.2s;
}

.player-controls button:hover {
    color: var(--text-color);
}

.player-controls button.active {
    color: var(--primary-color);
}

.player-controls .play-pause {
    background-color: var(--text-color);
    color: var(--bg-color);
    width: 38px;
    height: 38px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    transition: 0.2s;
}

.player-controls .play-pause:hover {
    transform: scale(1.05);
    background-color: var(--primary-color);
    color: var(--text-color);
}

.progress-container {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 100%;
    font-size: 12px;
    color: var(--text-muted);
}

.progress-bar {
    flex: 1;
    height: 5px;
    background-color: var(--card-hover);
    border-radius: 5px;
    cursor: pointer;
    position: relative;
}

.progress {
    width: 0%;
    height: 100%;
    background-color: var(--text-color);
    border-radius: 5px;
    position: relative;
}

.progress-bar:hover .progress {
    background-color: var(--primary-color);
}

.player-right {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 200px;
    justify-content: flex-end;
}

.player-right i {
    color: var(--text-muted);
    font-size: 16px;
}

.player-right input[type="range"] {
    width: 100px;
    accent-color: var(--text-color);
    cursor: pointer;
}

/* Responsive */
@media (max-width: 768px) {
    .sidebar {
        display: none;
    }
    .song-list-header,
    .song-item {
        grid-template-columns: 40px 1fr 60px;
    }
    .song-list-header span:nth-child(3),
    .song-item .album-name {
        display: none;
    }
}

const tracks = [
    {
        id: 1,
        title: "Nevada",
        artist: "Vicetone ft. Cozi Zuehlsdorff",
        album: "Monstercat Best",
        duration: "3:25",
        cover: "https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=100",
        audioUrl: "https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3"
    },
    {
        id: 2,
        title: "Spectre",
        artist: "Alan Walker",
        album: "NCS Release",
        duration: "3:48",
        cover: "https://images.unsplash.com/photo-1514525253161-7a46d19cd819?w=100",
        audioUrl: "https://www.soundhelix.com/examples/mp3/SoundHelix-Song-2.mp3"
    },
    {
        id: 3,
        title: "Faded",
        artist: "Alan Walker",
        album: "Different World",
        duration: "3:32",
        cover: "https://images.unsplash.com/photo-1470225620780-dba8ba36b745?w=100",
        audioUrl: "https://www.soundhelix.com/examples/mp3/SoundHelix-Song-3.mp3"
    },
    {
        id: 4,
        title: "Unity",
        artist: "TheFatRat",
        album: "TheFatRat Essentials",
        duration: "4:08",
        cover: "https://images.unsplash.com/photo-1508700115892-45ecd05ae2ad?w=100",
        audioUrl: "https://www.soundhelix.com/examples/mp3/SoundHelix-Song-4.mp3"
    },
    {
        id: 5,
        title: "Energy",
        artist: "Bensound",
        album: "Acoustic Indie",
        duration: "2:59",
        cover: "https://images.unsplash.com/photo-1519671482749-fd09be7ccebf?w=100",
        audioUrl: "https://www.soundhelix.com/examples/mp3/SoundHelix-Song-5.mp3"
    },
    {
        id: 6,
        title: "Sunny",
        artist: "Bensound",
        album: "Vlog Music",
        duration: "4:21",
        cover: "https://images.unsplash.com/photo-1526478806334-5fd488fcaabc?w=100",
        audioUrl: "https://www.soundhelix.com/examples/mp3/SoundHelix-Song-6.mp3"
    }
];

let currentTrackIndex = 0;
let isPlaying = false;
let isShuffle = false;
let isRepeat = false;
let favorites = JSON.parse(localStorage.getItem('favorites')) || [];

// DOM Elements
const audioElement = document.getElementById('audio-element');
const playPauseBtn = document.getElementById('play-pause-btn');
const playIcon = document.getElementById('play-icon');
const prevBtn = document.getElementById('prev-btn');
const nextBtn = document.getElementById('next-btn');
const shuffleBtn = document.getElementById('shuffle-btn');
const repeatBtn = document.getElementById('repeat-btn');
const progressBar = document.getElementById('progress-bar');
const progress = document.getElementById('progress');
const currentTimeEl = document.getElementById('current-time');
const durationEl = document.getElementById('duration');
const volumeSlider = document.getElementById('volume-slider');
const songListEl = document.getElementById('song-list');
const searchInput = document.getElementById('search-input');
const btnPlayAll = document.getElementById('btn-play-all');

const playerCover = document.getElementById('player-cover');
const playerTitle = document.getElementById('player-title');
const playerArtist = document.getElementById('player-artist');
const playerHeart = document.getElementById('player-heart');

// Initialize App
function init() {
    renderSongs(tracks);
    loadTrack(currentTrackIndex);

    playPauseBtn.addEventListener('click', togglePlay);
    prevBtn.addEventListener('click', prevTrack);
    nextBtn.addEventListener('click', nextTrack);
    shuffleBtn.addEventListener('click', toggleShuffle);
    repeatBtn.addEventListener('click', toggleRepeat);
    audioElement.addEventListener('timeupdate', updateProgress);
    audioElement.addEventListener('ended', handleTrackEnd);
    progressBar.addEventListener('click', setProgress);
    volumeSlider.addEventListener('input', setVolume);
    searchInput.addEventListener('input', handleSearch);
    btnPlayAll.addEventListener('click', () => {
        currentTrackIndex = 0;
        loadTrack(currentTrackIndex);
        playTrack();
    });
    playerHeart.addEventListener('click', toggleFavorite);
}

// Render Songs List
function renderSongs(songsToRender) {
    songListEl.innerHTML = '';
    if (songsToRender.length === 0) {
        songListEl.innerHTML = '<p style="padding: 20px; color: #b3b3b3; text-align: center;">Không tìm thấy bài hát nào.</p>';
        return;
    }

    songsToRender.forEach((song, index) => {
        const isFav = favorites.includes(song.id);
        const isCurrent = tracks[currentTrackIndex].id === song.id;
        const songItem = document.createElement('div');
        songItem.className = `song-item ${isCurrent ? 'active' : ''}`;
        songItem.innerHTML = `
            <span class="song-index">${index + 1}</span>
            <div class="song-details">
                <img src="${song.cover}" alt="${song.title}">
                <div class="title-artist">
                    <h5>${song.title}</h5>
                    <p>${song.artist}</p>
                </div>
            </div>
            <span class="album-name">${song.album}</span>
            <span class="song-duration">${song.duration}</span>
        `;
        songItem.addEventListener('click', () => {
            const actualIndex = tracks.findIndex(t => t.id === song.id);
            currentTrackIndex = actualIndex;
            loadTrack(currentTrackIndex);
            playTrack();
            renderSongs(tracks);
        });
        songListEl.appendChild(songItem);
    });
}

// Load Track
function loadTrack(index) {
    const song = tracks[index];
    audioElement.src = song.audioUrl;
    playerCover.src = song.cover;
    playerTitle.textContent = song.title;
    playerArtist.textContent = song.artist;

    if (favorites.includes(song.id)) {
        playerHeart.className = "fa-solid fa-heart active";
    } else {
        playerHeart.className = "fa-regular fa-heart";
    }
}

// Play / Pause
function togglePlay() {
    if (isPlaying) {
        pauseTrack();
    } else {
        playTrack();
    }
}

function playTrack() {
    isPlaying = true;
    audioElement.play();
    playIcon.className = "fa-solid fa-pause";
}

function pauseTrack() {
    isPlaying = false;
    audioElement.pause();
    playIcon.className = "fa-solid fa-play";
}

// Next / Prev
function nextTrack() {
    if (isShuffle) {
        currentTrackIndex = Math.floor(Math.random() * tracks.length);
    } else {
        currentTrackIndex = (currentTrackIndex + 1) % tracks.length;
    }
    loadTrack(currentTrackIndex);
    playTrack();
    renderSongs(tracks);
}

function prevTrack() {
    currentTrackIndex = (currentTrackIndex - 1 + tracks.length) % tracks.length;
    loadTrack(currentTrackIndex);
    playTrack();
    renderSongs(tracks);
}

// Progress Bar
function updateProgress() {
    const { duration, currentTime } = audioElement;
    if (isNaN(duration)) return;
    const progressPercent = (currentTime / duration) * 100;
    progress.style.width = `${progressPercent}%`;

    const currentMinutes = Math.floor(currentTime / 60);
    const currentSeconds = Math.floor(currentTime % 60);
    currentTimeEl.textContent = `${currentMinutes}:${currentSeconds < 10 ? '0' : ''}${currentSeconds}`;

    const durationMinutes = Math.floor(duration / 60);
    const durationSeconds = Math.floor(duration % 60);
    if (!isNaN(duration)) {
        durationEl.textContent = `${durationMinutes}:${durationSeconds < 10 ? '0' : ''}${durationSeconds}`;
    }
}

function setProgress(e) {
    const width = this.clientWidth;
    const clickX = e.offsetX;
    const duration = audioElement.duration;
    audioElement.currentTime = (clickX / width) * duration;
}

// Volume
function setVolume() {
    audioElement.volume = volumeSlider.value;
}

// Shuffle & Repeat
function toggleShuffle() {
    isShuffle = !isShuffle;
    shuffleBtn.classList.toggle('active', isShuffle);
}

function toggleRepeat() {
    isRepeat = !isRepeat;
    repeatBtn.classList.toggle('active', isRepeat);
}

function handleTrackEnd() {
    if (isRepeat) {
        audioElement.currentTime = 0;
        playTrack();
    } else {
        nextTrack();
    }
}

// Search
function handleSearch(e) {
    const keyword = e.target.value.toLowerCase();
    const filtered = tracks.filter(song => 
        song.title.toLowerCase().includes(keyword) || 
        song.artist.toLowerCase().includes(keyword) ||
        song.album.toLowerCase().includes(keyword)
    );
    renderSongs(filtered);
}

// Favorites
function toggleFavorite() {
    const currentSong = tracks[currentTrackIndex];
    const index = favorites.indexOf(currentSong.id);
    if (index > -1) {
        favorites.splice(index, 1);
        playerHeart.className = "fa-regular fa-heart";
    } else {
        favorites.push(currentSong.id);
        playerHeart.className = "fa-solid fa-heart active";
    }
    localStorage.setItem('favorites', JSON.stringify(favorites));
    renderSongs(tracks);
}

// Navigation tabs
const navItems = document.querySelectorAll('.nav-menu li');
navItems.forEach(item => {
    item.addEventListener('click', () => {
        navItems.forEach(nav => nav.classList.remove('active'));
        item.classList.add('active');
        const tab = item.getAttribute('data-tab');
        if (tab === 'favorites') {
            const favSongs = tracks.filter(s => favorites.includes(s.id));
            renderSongs(favSongs);
        } else {
            renderSongs(tracks);
        }
    });
});

// Run init on load
window.addEventListener('DOMContentLoaded', init);
